// 新轮目录、独立尾与四项真实效果对应；旧档没有新尾和新成功词。
#define POLITICAL_SUCCESSOR_ROUND_RECEIPTS_FIXTURE_ONLY
#include "political_successor_round_receipts_test.cpp"
#include "resident/domains/politics/successor_rounds/political_successor_round_profile.hpp"
int main(){try{
 RoundReceiptFixture f;PoliticalSuccessorRoundState empty;std::vector<std::pair<StableId,StableId>> modules={{"politics","1"},{"family_life","1"},{"task_message_notices","1"},{"task_message_handoffs","2"},{"political_successions","1"},{political_successor_rounds_domain,"1"}};
 check(take(political_successor_round_selected_version(modules))==1,"new independent module uses original succession prerequisites");check(validate_political_successor_round_layout(f.common,modules,&empty).ok,"selected empty new tail is exact");check(!validate_political_successor_round_layout(f.common,modules,nullptr).ok,"missing selected tail rejected");auto bad=modules;bad.erase(bad.end()-2);check(!political_successor_round_selected_version(bad).ok,"original succession module required");bad=modules;bad.push_back(modules.back());check(!political_successor_round_selected_version(bad).ok,"duplicate version refused");bad=modules;bad.back().second="2";check(!political_successor_round_selected_version(bad).ok,"unknown new version refused");modules.pop_back();check(validate_political_successor_round_layout(f.common,modules,nullptr).ok,"old profile retains exact absent new tail");check(!validate_political_successor_round_layout(f.common,modules,&empty).ok,"even empty orphan tail rejected");
 f.install();auto n=f.commit_round("candidate",f.propose(),2);check(!validate_political_successor_round_layout(f.common,modules,nullptr).ok,"actual new fact cannot enter old profile");check(validate_political_successor_round_fact_header(f.common,f.rounds,*f.common.state().facts.find(n)).ok,"exact real new nomination covers its header");auto forged=f.rounds;PoliticalSuccessorRoundAnswer a;a.id=n;forged.answers.insert(n,a);check(!validate_political_successor_round_fact_header(f.common,forged,*f.common.state().facts.find(n)).ok,"cross-table duplicate payload rejected");
 PoliticsEffects e;e.fact_ids={"political_successor_round_acceptance:2"};check(valid_political_successor_round_effect(political_successor_round_answer_command,e),"future willingness has no Office effect");e.receipt_ids={"organization:3"};check(!valid_political_successor_round_effect(political_successor_round_answer_command,e),"acceptance alone cannot install Office");e.fact_ids={"political_successor_round_accession:2"};check(valid_political_successor_round_effect(political_successor_round_accede_command,e),"formal accession names exactly original Office change");e.receipt_ids.clear();check(!valid_political_successor_round_effect(political_successor_round_accede_command,e),"formal accession cannot lose Office source");e.fact_ids={"political_successor_round_nomination:02"};check(!valid_political_successor_round_effect(political_successor_round_nominate_command,e),"noncanonical instance rejected");
 std::cout<<checks<<" new-round profile assertions; no World run\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
